SCORE = 'Scored from the survey text and the archive record, 9 Nov 2026 (research/sweep_2026-11_mirka_cryptoworld/); no image seen'
PLZ_ACC = ("description only (Mírka's survey; ARON gives folder level without a cipher note); no digital objects. Scans to order from "
           "SOA Plzeň, pracoviště Klášter u Nepomuka")
PRIOR = ('open as far as checked (9 Nov 2026): known.py on the shelfmark and correspondents finds nothing; web searches on the correspondents '
         'with cipher/decipher found no edition or decipherment; Mírka (2012-13) states the text is not deciphered or gives no reading; '
         'the Antal-Zajac-Mírka HistoCrypt papers (Rabenhaupt 2022, Marburg keys 2022, Slovakia 2023) do not cover it')


def row(**k):
    base = dict(region='Central Europe', cls='B', seen='catalogue', source=SRC, score_note=SCORE, prior_art=PRIOR,
                needs_archive_scan='yes', access_note=PLZ_ACC)
    base.update(k)
    return base


